namespace sv_880a1b764d204d5cb004d8245c1a7857.Services;

public record Doctor(string Name, bool AcceptsSelfPay);

public record ValidationError(string Field, string Message);

public record ValidationResult(bool IsValid, List<ValidationError> Errors)
{
    public static ValidationResult Success() => new(true, []);
    public static ValidationResult Failure(List<ValidationError> errors) => new(false, errors);
}

public interface IAppointmentService
{
    Task<List<Doctor>> GetDoctorsAsync();
    Task<List<string>> GetAvailableTimeSlotsAsync(string doctorName, DateOnly date);
    Task<ValidationResult> ValidatePatientAsync(
        string email, string insuranceProvider, string doctorName, string timeSlot);
}

public class AppointmentService : IAppointmentService
{
    private static readonly List<Doctor> Doctors =
    [
        new("Dr. Smith", false),
        new("Dr. Johnson", true),
        new("Dr. Williams", true),
        new("Dr. Brown", false),
        new("Dr. Davis", true)
    ];

    private static readonly List<string> AllSlots =
    [
        "9:00 AM", "9:30 AM", "10:00 AM", "10:30 AM",
        "11:00 AM", "11:30 AM", "1:00 PM", "1:30 PM",
        "2:00 PM", "2:30 PM", "3:00 PM", "3:30 PM",
        "4:00 PM", "4:30 PM"
    ];

    public Task<List<Doctor>> GetDoctorsAsync()
    {
        return Task.FromResult(Doctors);
    }

    public Task<List<string>> GetAvailableTimeSlotsAsync(string doctorName, DateOnly date)
    {
        // Simulate different availability per doctor/date
        var hash = (doctorName.GetHashCode() ^ date.GetHashCode()) & 0x7FFFFFFF;
        var available = AllSlots.Where((_, i) => (hash + i) % 3 != 0).ToList();
        return Task.FromResult(available);
    }

    public Task<ValidationResult> ValidatePatientAsync(
        string email, string insuranceProvider, string doctorName, string timeSlot)
    {
        var errors = new List<ValidationError>();

        // Reject "taken@example.com" for outstanding balance
        if (string.Equals(email, "taken@example.com", StringComparison.OrdinalIgnoreCase))
        {
            errors.Add(new("Email", "Account has outstanding balance"));
        }

        // Reject "None" insurance with a doctor who doesn't accept self-pay
        if (string.Equals(insuranceProvider, "None", StringComparison.Ordinal))
        {
            var doctor = Doctors.FirstOrDefault(d => d.Name == doctorName);
            if (doctor is not null && !doctor.AcceptsSelfPay)
            {
                errors.Add(new("Doctor", "Selected doctor does not accept self-pay patients"));
            }
        }

        // Reject "10:00 AM" as a taken slot (race condition simulation)
        if (string.Equals(timeSlot, "10:00 AM", StringComparison.Ordinal))
        {
            errors.Add(new("TimeSlot", "This slot is no longer available"));
        }

        return Task.FromResult(errors.Count > 0
            ? ValidationResult.Failure(errors)
            : ValidationResult.Success());
    }
}

@page "/book-appointment"
@rendermode InteractiveServer
@using sv_880a1b764d204d5cb004d8245c1a7857.Services
@inject IAppointmentService AppointmentSvc

<PageTitle>Book Appointment</PageTitle>

<h3 class="mb-4">Book a Medical Appointment</h3>

<EditForm Model="Model" OnValidSubmit="HandleSubmit" FormName="bookAppointment">
    <DataAnnotationsValidator />

    @* ---- STEP 1: Patient Information ---- *@
    <fieldset>
        <legend>Step 1 — Patient Information</legend>

        <div class="mb-3">
            <label class="form-label" for="patientName">Patient Name</label>
            <InputText id="patientName" class="form-control" @bind-Value="Model.PatientName" />
            <ValidationMessage For="() => Model.PatientName" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="email">Email</label>
            <InputText id="email" class="form-control" @bind-Value="Model.Email" />
            <ValidationMessage For="() => Model.Email" />
            @if (serverErrors.TryGetValue("Email", out var emailErr))
            {
                <div class="validation-message">@emailErr</div>
            }
        </div>

        <div class="mb-3">
            <label class="form-label" for="phone">Phone</label>
            <InputText id="phone" class="form-control" @bind-Value="Model.Phone" />
            <ValidationMessage For="() => Model.Phone" />
        </div>

        <div class="mb-3">
            <label class="form-label" for="insurance">Insurance Provider</label>
            <InputSelect id="insurance" class="form-select" @bind-Value="Model.InsuranceProvider">
                <option value="">-- Select --</option>
                <option value="Aetna">Aetna</option>
                <option value="BlueCross">BlueCross</option>
                <option value="Cigna">Cigna</option>
                <option value="UnitedHealth">UnitedHealth</option>
                <option value="None">None</option>
            </InputSelect>
            <ValidationMessage For="() => Model.InsuranceProvider" />
        </div>

        @if (!showStep2)
        {
            <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
                Next &rarr;
            </button>
        }
    </fieldset>

    @* ---- STEP 2: Appointment Details ---- *@
    @if (showStep2)
    {
        <fieldset class="mt-4">
            <legend>Step 2 — Appointment Details</legend>

            <div class="mb-3">
                <label class="form-label" for="doctor">Preferred Doctor</label>
                <InputSelect id="doctor" class="form-select" @bind-Value="Model.Doctor"
                             @bind-Value:after="OnDoctorOrDateChanged">
                    <option value="">-- Select --</option>
                    @foreach (var doc in doctors)
                    {
                        <option value="@doc.Name">@doc.Name</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.Doctor" />
                @if (serverErrors.TryGetValue("Doctor", out var docErr))
                {
                    <div class="validation-message">@docErr</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="date">Date</label>
                <InputDate id="date" class="form-control" @bind-Value="Model.AppointmentDate"
                           @bind-Value:after="OnDoctorOrDateChanged" />
                <ValidationMessage For="() => Model.AppointmentDate" />
            </div>

            <div class="mb-3">
                <label class="form-label" for="timeSlot">Time Slot</label>
                <InputSelect id="timeSlot" class="form-select" @bind-Value="Model.TimeSlot">
                    <option value="">-- Select --</option>
                    @foreach (var slot in availableSlots)
                    {
                        <option value="@slot">@slot</option>
                    }
                </InputSelect>
                <ValidationMessage For="() => Model.TimeSlot" />
                @if (serverErrors.TryGetValue("TimeSlot", out var slotErr))
                {
                    <div class="validation-message">@slotErr</div>
                }
            </div>

            <div class="mb-3">
                <label class="form-label" for="reason">Reason for Visit</label>
                <InputTextArea id="reason" class="form-control" rows="3" @bind-Value="Model.Reason" />
                <ValidationMessage For="() => Model.Reason" />
            </div>

            <div class="d-flex gap-2">
                <button type="button" class="btn btn-outline-secondary" @onclick="BackToStep1">
                    &larr; Back
                </button>
                <button type="button" class="btn btn-info" @onclick="CheckAvailability" disabled="@isSubmitting">
                    Check Availability
                </button>
                <button type="submit" class="btn btn-success" disabled="@(!availabilityChecked || isSubmitting)">
                    Book Appointment
                </button>
            </div>
        </fieldset>
    }
</EditForm>

@if (isBooked)
{
    <div class="alert alert-success mt-4" role="alert">
        Appointment booked successfully!
    </div>
}

@code {
    private AppointmentModel Model { get; set; } = new();
    private List<Doctor> doctors = [];
    private List<string> availableSlots = [];
    private Dictionary<string, string> serverErrors = new();
    private bool showStep2;
    private bool availabilityChecked;
    private bool isSubmitting;
    private bool isBooked;

    private EditContext? editContext;

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        // Validate only step-1 fields
        editContext = new EditContext(Model);
        var isValid = true;
        var messages = new ValidationMessageStore(editContext);

        if (string.IsNullOrWhiteSpace(Model.PatientName))
        {
            messages.Add(() => Model.PatientName, "Patient Name is required.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.Email))
        {
            messages.Add(() => Model.Email, "Email is required.");
            isValid = false;
        }
        else if (!System.ComponentModel.DataAnnotations.Validator.TryValidateProperty(
            Model.Email,
            new System.ComponentModel.DataAnnotations.ValidationContext(Model) { MemberName = nameof(Model.Email) },
            null))
        {
            messages.Add(() => Model.Email, "Please enter a valid email address.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.Phone))
        {
            messages.Add(() => Model.Phone, "Phone is required.");
            isValid = false;
        }
        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
        {
            messages.Add(() => Model.InsuranceProvider, "Insurance Provider is required.");
            isValid = false;
        }

        editContext.NotifyValidationStateChanged();

        if (isValid)
        {
            serverErrors.Clear();
            showStep2 = true;
            availabilityChecked = false;
        }
    }

    private async Task OnDoctorOrDateChanged()
    {
        availabilityChecked = false;
        serverErrors.Remove("Doctor");
        serverErrors.Remove("TimeSlot");
        Model.TimeSlot = string.Empty;

        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            availableSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(
                Model.Doctor, DateOnly.FromDateTime(Model.AppointmentDate.Value));
        }
        else
        {
            availableSlots = [];
        }
    }

    private async Task CheckAvailability()
    {
        serverErrors.Clear();
        availabilityChecked = false;

        // Re-validate step-2 fields client-side first
        editContext = new EditContext(Model);
        var messages = new ValidationMessageStore(editContext);
        var isValid = true;

        // Step 1 re-check
        if (string.IsNullOrWhiteSpace(Model.PatientName))
        { messages.Add(() => Model.PatientName, "Patient Name is required."); isValid = false; }
        if (string.IsNullOrWhiteSpace(Model.Email))
        { messages.Add(() => Model.Email, "Email is required."); isValid = false; }
        if (string.IsNullOrWhiteSpace(Model.Phone))
        { messages.Add(() => Model.Phone, "Phone is required."); isValid = false; }
        if (string.IsNullOrWhiteSpace(Model.InsuranceProvider))
        { messages.Add(() => Model.InsuranceProvider, "Insurance Provider is required."); isValid = false; }

        // Step 2
        if (string.IsNullOrWhiteSpace(Model.Doctor))
        { messages.Add(() => Model.Doctor, "Please select a doctor."); isValid = false; }
        if (!Model.AppointmentDate.HasValue)
        { messages.Add(() => Model.AppointmentDate, "Date is required."); isValid = false; }
        else if (Model.AppointmentDate.Value.Date <= DateTime.Today)
        { messages.Add(() => Model.AppointmentDate, "Date must be in the future."); isValid = false; }
        if (string.IsNullOrWhiteSpace(Model.TimeSlot))
        { messages.Add(() => Model.TimeSlot, "Please select a time slot."); isValid = false; }
        if (string.IsNullOrWhiteSpace(Model.Reason))
        { messages.Add(() => Model.Reason, "Reason for visit is required."); isValid = false; }
        else if (Model.Reason.Length > 500)
        { messages.Add(() => Model.Reason, "Reason must be 500 characters or fewer."); isValid = false; }

        editContext.NotifyValidationStateChanged();
        if (!isValid) return;

        // Server-side validation
        isSubmitting = true;
        try
        {
            var result = await AppointmentSvc.ValidatePatientAsync(
                Model.Email, Model.InsuranceProvider, Model.Doctor, Model.TimeSlot);

            if (!result.IsValid)
            {
                foreach (var err in result.Errors)
                {
                    serverErrors[err.Field] = err.Message;
                }
            }
            else
            {
                availabilityChecked = true;
            }
        }
        finally
        {
            isSubmitting = false;
        }
    }

    private void BackToStep1()
    {
        showStep2 = false;
        availabilityChecked = false;
        serverErrors.Clear();
    }

    private void HandleSubmit()
    {
        if (!availabilityChecked) return;
        isBooked = true;
    }

    public class AppointmentModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Patient Name is required.")]
        public string PatientName { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Email is required.")]
        [System.ComponentModel.DataAnnotations.EmailAddress(ErrorMessage = "Please enter a valid email address.")]
        public string Email { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Phone is required.")]
        public string Phone { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Insurance Provider is required.")]
        public string InsuranceProvider { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a doctor.")]
        public string Doctor { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Date is required.")]
        public DateTime? AppointmentDate { get; set; }

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Please select a time slot.")]
        public string TimeSlot { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Reason for visit is required.")]
        [System.ComponentModel.DataAnnotations.MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer.")]
        public string Reason { get; set; } = string.Empty;
    }
}

